// Prompts, examples and explanations below are original. Links identify related platform problems.
export const examChallenges=[];
function C(id,lesson,title,prompt,cases,hint,solution,steps,checks,links=[],level='进阶'){
 examChallenges.push({id:'coding-'+id,lesson,title:'手写：'+title,prompt,cases,hint,solution,steps,checks,analysis:steps.join('\n'),links,level,kind:links.length?'C++ 算法编程':'C/C++ 嵌入式编程',source:links.length?'同类平台题 · 站内题干与解析独立编写':'原创编程题'});
}
C('longest-window','ds-hash','无重复字节的最长连续片段','给定字节字符串s，返回不包含重复字节的最长连续片段长度。字符集按0..255处理，不按Unicode码点；写出线性方案。',['"abcaef" → 5（bcaef）','"aaaa" → 1','"" → 0','"abba" → 2'], '记录每个字节上次出现位置；左边界只前进，不后退。',
'size_t longest(const std::string &s){\n    std::array<size_t,256> last{}; // 上次位置+1；0=没见过\n    size_t left=0,best=0;\n    for(size_t i=0;i<s.size();++i){\n        unsigned char c=static_cast<unsigned char>(s[i]);\n        left=std::max(left,last[c]);\n        best=std::max(best,i-left+1);\n        last[c]=i+1;\n    }\n    return best;\n}',
['不变量：窗口[left,i]无重复；若c上次在窗口内，就把left移到该位置之后。','last存位置+1，既能区分未出现，又避免用-1和size_t混算。left取max，防止abba里的旧a让窗口倒退。','每个字节只处理一次，时间O(n)，固定256项表空间O(1)。代码需<string>、<array>、<algorithm>。'],['空串、全相同、abba','以unsigned char作下标，避免负char','区别连续子串与不连续子序列'],[['力扣 3 无重复字符的最长子串','https://leetcode.cn/problems/longest-substring-without-repeating-characters/']]);
C('rotated-search','ds-binary','旋转有序数组查找','升序数组元素互异，经一次旋转后给出数组和target；返回匹配下标，不存在返回-1。要求O(log n)。本站另支持空数组。',['[8,10,12,1,3,5]，target=3 → 4','[8,10,12,1,3,5]，target=7 → -1','[] → -1','[4]，target=4 → 0'],'每轮至少一侧有序；先确认哪侧有序，再看目标是否在该侧范围。',
'int rotated(const std::vector<int>& a,int x){\n    // 题设数组长度不超过 INT_MAX\n    int lo=0,hi=static_cast<int>(a.size())-1;\n    while(lo<=hi){\n        int mid=lo+(hi-lo)/2;\n        if(a[mid]==x) return mid;\n        if(a[lo]<=a[mid]){\n            if(a[lo]<=x && x<a[mid]) hi=mid-1;\n            else lo=mid+1;\n        }else{\n            if(a[mid]<x && x<=a[hi]) lo=mid+1;\n            else hi=mid-1;\n        }\n    }\n    return -1;\n}',
['闭区间[lo,hi]保留候选；元素互异时，左侧或右侧至少一段是升序。','比较target与有序段端点，可以排除整段；每轮至少排除mid，所以区间严格缩小。','O(log n)时间、O(1)额外空间；若允许大量重复值，此判断可能退化，不能直接承诺对数时间。'],['空数组、单元素、未旋转、首尾目标','严格区分<和<=边界','不要假定允许重复元素'],[['力扣 33 搜索旋转排序数组','https://leetcode.cn/problems/search-in-rotated-sorted-array/']]);
C('cycle-entry','ds-list','找到链表入环节点','不修改链表、不使用集合，返回入环的第一个节点地址；无环返回nullptr。Node具有next成员。',['A→B→C→D→B → 返回B','A→A → 返回A','A→B→nullptr → nullptr','nullptr → nullptr'],'先用快慢指针相遇，再让一根指针回到头部，两根都每次走一步。',
'Node *entry(Node *head){\n    Node *slow=head,*fast=head;\n    while(fast && fast->next){\n        slow=slow->next;\n        fast=fast->next->next;\n        if(slow==fast){\n            Node *p=head;\n            while(p!=slow){ p=p->next; slow=slow->next; }\n            return p;\n        }\n    }\n    return nullptr;\n}',
['无环时fast或fast->next最终为空；有环时快指针每轮相对慢指针多前进一步，因此环内最终相遇。','设头到入口为μ，入口到相遇点为x，环长λ。相遇时2(μ+x)=μ+x+kλ，所以μ+x=kλ；从头和相遇点各走μ步恰在入口相遇（距离按环长取模）。','时间O(n)，额外空间O(1)。比较节点地址而不是值，相同值不表示同一节点。'],['空链表、无环、头入环、单节点自环','fast->next判空后才能取next->next','需证明第二阶段为何到入口'],[['力扣 142 环形链表 II','https://leetcode.cn/problems/linked-list-cycle-ii/'],['先练牛客 BM6 判断链表中是否有环','https://www.nowcoder.com/practice/650474f313294468a4ded3ce0f7898b9']]);
C('daily-stack','ds-queue','下一次更高温度','给出每日整数温度，返回每一天还需等待几天才出现严格更高温度；之后都没有则填0。实现O(n)算法。',['[20,18,19,25] → [3,1,1,0]','[30,30,31] → [2,1,0]','[9,8,7] → [0,0,0]'],'栈存下标；当前温度更高时，逐个解决栈顶尚未等到更高温度的日子。',
'std::vector<int> waits(const std::vector<int>& t){\n    // 题设长度<=INT_MAX\n    std::vector<int> ans(t.size(),0),st;\n    for(int i=0;i<static_cast<int>(t.size());++i){\n        while(!st.empty() && t[i]>t[st.back()]){\n            int old=st.back(); st.pop_back();\n            ans[old]=i-old;\n        }\n        st.push_back(i);\n    }\n    return ans;\n}',
['栈中温度保持非递增；下标记录了需要返回的距离。','遇到严格更高的当前值，就解决比它小的栈顶并继续弹出；相等不能解决等待。','每个下标入栈一次、出栈至多一次，嵌套while总成本仍O(n)；栈与输出O(n)。'],['相等温度不弹出','栈存下标而不只是温度','递减序列与最后未解决项'],[['力扣 739 每日温度','https://leetcode.cn/problems/daily-temperatures/']]);
C('valid-bst','ds-tree','验证整棵二叉搜索树','节点值为int，严格BST不允许相等。实现验证，保证每个节点满足祖先传下来的全局范围；空树为true。',['根10，左5，5的右子12 → false','根2，左1，右3 → true','根2，左2 → false','空树 → true'],'递归传开区间(lo,hi)，不能只比较父子。边界类型要覆盖全部int。',
'bool check(Node *p,long long lo,long long hi){\n    if(!p) return true;\n    long long x=p->val;\n    if(x<=lo || x>=hi) return false;\n    return check(p->left,lo,x) && check(p->right,x,hi);\n}\nbool valid(Node *root){\n    return check(root,LLONG_MIN,LLONG_MAX);\n}',
['左子树的上界为当前值，右子树的下界为当前值，先前祖先的另一侧边界仍保留。','用long long边界而不是val±1，避免int最小/最大值处算术溢出；需要<climits>，Node有val/left/right。','时间O(n)，递归栈O(h)，极端退化树h=n；嵌入式小栈可用显式栈或限制深度。'],['祖先约束反例、重复值、INT_MIN/MAX','空树','说明递归空间随高度变化'],[['力扣 98 验证二叉搜索树','https://leetcode.cn/problems/validate-binary-search-tree/']]);
C('coin-dp','ds-dp','最少硬币数量','正整数面额，每种无限枚，amount范围0..10000。求凑出amount的最少枚数，不能凑出返回-1；使用动态规划，不假设贪心成立。',['[1,3,4]，6 → 2','[2,4]，7 → -1','[2]，0 → 0','空面额，5 → -1'],'dp[s]表示凑出s的最少枚数；枚举最后一枚硬币。',
'int coins_min(const std::vector<int>& coins,int amount){\n    const int inf=amount+1;\n    std::vector<int> dp(amount+1,inf); dp[0]=0;\n    for(int s=1;s<=amount;++s)\n        for(int c:coins)\n            if(c>0 && c<=s && dp[s-c]!=inf)\n                dp[s]=std::min(dp[s],dp[s-c]+1);\n    return dp[amount]==inf ? -1 : dp[amount];\n}',
['若最后一枚为c，之前金额s-c需dp[s-c]枚，因此候选为dp[s-c]+1。','按金额由小到大算，所有依赖已完成；不可达值保持inf，不能直接把其当有效方案。','时间O(amount×面额数)，空间O(amount)。amount有限保证inf和索引安全；通用接口还需校验负金额和内存预算。'],['零金额、不可达、重复面额','[1,3,4]击破贪心','空间在MCU上是否可接受'],[['力扣 322 零钱兑换','https://leetcode.cn/problems/coin-change/']]);
C('bounded-atoi','c-conversion','带溢出检查的十进制解析','实现bool parse_i32(const char *s,int32_t *out)。允许开头一个+/-，其余只能是0..9，不允许空串、空白或仅符号；超范围失败且不得修改*out。char为8bit。',['"2147483647" → 成功','"-2147483648" → 成功','"2147483648"、"+"、"1a" → 失败','"00012" → 12'],'用无符号幅值累积，负数边界允许2147483648；乘10前先检查(limit-digit)/10。',
'bool parse_i32(const char *s,int32_t *out){\n    if(!s || !out) return false;\n    bool neg=false;\n    if(*s==\'-\' || *s==\'+\'){ neg=(*s==\'-\'); ++s; }\n    if(!*s) return false;\n    uint32_t limit=neg?UINT32_C(2147483648):UINT32_C(2147483647);\n    uint32_t mag=0;\n    for(;*s;++s){\n        if(*s<\'0\' || *s>\'9\') return false;\n        uint32_t d=(uint32_t)(*s-\'0\');\n        if(mag>(limit-d)/10) return false;\n        mag=mag*10+d;\n    }\n    int32_t value;\n    if(neg && mag==UINT32_C(2147483648)) value=INT32_MIN;\n    else value=neg?-(int32_t)mag:(int32_t)mag;\n    *out=value; return true;\n}',
['负范围比正范围多一个值，不能先把2147483648转换成int32_t再随意取负。','检查在乘法前完成，拒绝非法字符时不写out，所以失败保留旧输出。','最后单独处理INT32_MIN；时间O(字符串长度)，空间O(1)，需要<stdint.h>和<stdbool.h>。'],['两端边界与再超出1','空串、仅符号、非法字符、前导零','失败不改输出、NULL参数']);
C('bit-update','c-bits','安全更新普通寄存器字段','实现bool replace_bits(uint32_t old,unsigned pos,unsigned width,uint32_t value,uint32_t *out)。width取1..32，字段不可超过32位，value须能放入字段。无效输入不改*out。只是整数计算，不直接操作MMIO。',['old=0xABCD,pos=4,width=4,value=2 → 0xAB2D','pos=0,width=32,value=UINT32_MAX → UINT32_MAX','pos=31,width=2 → 失败','width=4,value=16 → 失败'],'避免1u<<32；width==32单独处理，先检查pos<32再算32-pos。',
'bool replace_bits(uint32_t old,unsigned pos,unsigned width,\n                  uint32_t value,uint32_t *out){\n    if(!out || pos>=32 || width==0 || width>32-pos) return false;\n    uint32_t low=(width==32)?UINT32_MAX:((UINT32_C(1)<<width)-1);\n    if(value>low) return false;\n    uint32_t mask=low<<pos;\n    *out=(old & ~mask) | (value<<pos);\n    return true;\n}',
['先检验字段范围，让所有后续移位次数严格小于32；width=32必然pos=0。','low表示未移位的字段全1掩码；先清字段，再写新值，其他位不受影响。','O(1)时间空间。用于硬件时还需核查W1C、保留位和并发读改写，整数函数不自动解决这些。'],['width=32和pos=31,width=1','超范围value不截断','验证其他位完全保持']);
C('tick-wrap','r-delay','可跨回绕的超时判断','计时器为uint32_t毫秒单调递增并回绕。实现expired(now,start,timeout)。假设从start到本次检查的真实经过时间少于一次完整2^32周期；说明若错过一整圈为什么无法判断。',['start=0xFFFFFFF0,now=0x10,timeout=32 → true','相同时间、timeout=1 → false','timeout=0 → true'],'先做无符号减法，不比较now>=start+timeout。',
'bool expired(uint32_t now,uint32_t start,uint32_t timeout){\n    return (uint32_t)(now-start)>=timeout;\n}',
['无符号减法按模2^32得到差值；题设真实经过时间<2^32时，差值就是所需经过时间。','例子从0xFFFFFFF0到0x10经过32ms，模减法结果32；把start+timeout作为绝对截止可能在回绕附近误判。','若经过一整圈又回到相同now，单个32位值无法表达圈数，需要更宽计时或额外计数。O(1)。'],['跨回绕、刚好到阈值、零超时','明确不到完整周期的前提','区别elapsed计算与有符号截止时间比较']);
C('safe-packet','p-packet','带边界检查的协议字段解码','帧为1字节type、2字节大端length、length字节payload。写函数返回payload地址和长度；不足、超上限失败，不复制载荷。输入缓冲区需在输出使用期间有效。',['[01,00,02,AA,BB] → payload指向AA,len=2','只有2字节 → 失败','length=513,max=512 → 失败','头中length=4但仅2字节载荷 → 失败'],'先保证至少3字节，再解码；用length>n-3检查，避免length+3回绕。',
'bool decode(const uint8_t *buf,size_t n,size_t max,\n            const uint8_t **payload,size_t *len){\n    if(!buf || !payload || !len || n<3) return false;\n    size_t k=((size_t)buf[1]<<8)|buf[2];\n    if(k>max || k>n-3) return false;\n    *payload=buf+3; *len=k; return true;\n}',
['长度检查在每次读取之前：n<3时不能读buf[2]。','逐字节解码不依赖端序/对齐；比较k与n-3避免先计算大数加法。','返回的是借用视图，不拥有内存；本函数允许尾部额外数据，调用者可用3+k作为消费量继续解析。O(1)，不证明校验/认证正确。'],['零长度、截断头、截断载荷、尾随下一帧','输出参数失败不改','不得在缓冲释放或DMA覆盖后继续读']);
C('unique-buffer','cpp-copy','可移动的独占缓冲区类','C++17实现Buffer：申请n字节，禁止复制，支持移动构造与移动赋值。说明自移动赋值、旧资源释放和异常保证。采用unique_ptr表达所有权。',['Buffer a(16); Buffer b(std::move(a)); → b拥有16字节','Buffer c(8); c=std::move(b); → c原8字节释放','c=std::move(c); → 本实现保留原对象'],'把资源放进unique_ptr数组，size与指针一起转移；显式处理自移动。',
'class Buffer {\n    std::unique_ptr<unsigned char[]> p;\n    size_t n=0;\npublic:\n    explicit Buffer(size_t size):p(size?new unsigned char[size]:nullptr),n(size){}\n    Buffer(const Buffer&)=delete;\n    Buffer& operator=(const Buffer&)=delete;\n    Buffer(Buffer&& other) noexcept\n        :p(std::move(other.p)),n(std::exchange(other.n,0)){}\n    Buffer& operator=(Buffer&& other) noexcept{\n        if(this!=&other){\n            p=std::move(other.p);\n            n=std::exchange(other.n,0);\n        }\n        return *this;\n    }\n    size_t size() const noexcept{return n;}\n    unsigned char* data() noexcept{return p.get();}\n};',
['unique_ptr数组会匹配delete[]，移动赋值会先处理目标旧资源，不需手动delete。','复制操作删除，防止隐式共享独占指针；移动后源指针为空、n=0，析构安全。','需<memory>、<utility>、<cstddef>；申请失败抛异常，移动路径不申请。分配O(n)空间，所有权转移O(1)，本例字节未初始化。'],['编译期禁止复制','移动后源大小0、目标大小正确','自移动、旧资源释放、零长度']);
C('median-stream','ds-heap','流式第k大：有界最小堆','持续读取整数流，k固定且>=1。实现add(x)，已有至少k个数时返回第k大，否则报告尚不足。允许重复值，第k大按排序位置计数。要求只保留O(k)内存。',['k=3，输入5,1,5,2 → 第4次返回2','k=1，输入3,2,8 → 返回3,3,8'],'保留最大的k项，堆顶正好是第k大；不足时全部保留。',
'class Kth {\n    size_t k;\n    std::priority_queue<int,std::vector<int>,std::greater<int>> heap;\npublic:\n    explicit Kth(size_t count):k(count){\n        if(k==0) throw std::invalid_argument("k must be positive");\n    }\n    std::optional<int> add(int x){\n        if(heap.size()<k) heap.push(x);\n        else if(x>heap.top()){heap.pop();heap.push(x);}\n        if(heap.size()<k) return std::nullopt;\n        return heap.top();\n    }\n};',
['堆中保留已见数据中最大的k项；新项不大于堆顶时无需替换，重复值仍按个数计入。','每次O(log k)上界，k=1时常数；空间O(k)。需<queue>、<vector>、<functional>、<optional>、<stdexcept>。','这是流式堆方法，相关力扣215另有线性时间要求；本站练习不把O(n log k)冒充原题的O(n)算法。'],['k=1、尚不足k、重复数据','不存在无限增长存储','说明堆方案与原题线性目标差别'],[['相关力扣 215 数组中的第K个最大元素','https://leetcode.cn/problems/kth-largest-element-in-an-array/']],'挑战');
